INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Auswahl der Programmiersprache in TDD entscheidend für die Effektivität der Testentwicklung?', 2, '[{"text": "Ja", "correct": true, "because": "Sprache beeinflusst Testwerkzeuge"}, {"text": "Nein", "correct": false, "because": "Effektivität abhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann TDD unabhängig von der Programmiersprache erfolgreich angewendet werden?', 2, '[{"text": "Ja", "correct": true, "because": "TDD ist sprachunabhängig"}, {"text": "Nein", "correct": false, "because": "Prinzipien universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl einer Programmiersprache für TDD immer Test-Frameworks verfügbar sein?', 2, '[{"text": "Ja", "correct": true, "because": "Frameworks erleichtern TDD"}, {"text": "Nein", "correct": false, "because": "Werkzeuge wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können dynamische Programmiersprachen wie Python die Testentwicklung in TDD vereinfachen?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibilität hilft"}, {"text": "Nein", "correct": false, "because": "Vorteil durch Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Auswahl einer Programmiersprache in TDD nur von der Teamkompetenz abhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Projektanforderungen zählen"}, {"text": "Ja", "correct": false, "because": "Mehrere Faktoren relevant"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl einer Programmiersprache für TDD am wichtigsten?', 2, '[{"text": "Verfügbarkeit von Test-Frameworks", "correct": true, "because": "Unterstützt TDD-Zyklus"}, {"text": "Code-Komplexität", "correct": false, "because": "Sekundär"}, {"text": "Kosten der Sprache", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmiersprache wird oft für TDD wegen ihrer starken Test-Community bevorzugt?', 3, '[{"text": "Python", "correct": true, "because": "Tools wie pytest beliebt"}, {"text": "C++", "correct": false, "because": "Weniger TDD-Fokus"}, {"text": "PHP", "correct": false, "because": "Kleinere TDD-Community"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Programmiersprache beeinflusst die TDD-Umsetzung am meisten?', 2, '[{"text": "Unterstützung für Unit-Tests", "correct": true, "because": "TDD basiert darauf"}, {"text": "Laufzeitgeschwindigkeit", "correct": false, "because": "Sekundär"}, {"text": "Syntax-Komplexität", "correct": false, "because": "Weniger entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Warum ist Java eine beliebte Wahl für TDD?', 2, '[{"text": "Starke Test-Frameworks wie JUnit", "correct": true, "because": "Gut unterstützt"}, {"text": "Hohe Komplexität", "correct": false, "because": "Nicht primär"}, {"text": "Kostenfreiheit", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium sollte bei der Auswahl einer Sprache für TDD nicht übersehen werden?', 2, '[{"text": "Teamkompetenz", "correct": true, "because": "Erfahrung entscheidend"}, {"text": "Code-Länge", "correct": false, "because": "Weniger wichtig"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sollten bei der Auswahl einer Programmiersprache für TDD berücksichtigt werden?', 4, '[{"text": "Verfügbarkeit von Test-Frameworks", "correct": true, "because": "Unterstützt TDD"}, {"text": "Teamkompetenz", "correct": true, "because": "Erfahrung wichtig"}, {"text": "Code-Komplexität", "correct": false, "because": "Sekundär"}, {"text": "Community-Unterstützung", "correct": true, "because": "Hilft bei Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmiersprachen sind für TDD besonders geeignet?', 3, '[{"text": "Java", "correct": true, "because": "JUnit verfügbar"}, {"text": "Python", "correct": true, "because": "pytest und unittest"}, {"text": "Assembly", "correct": false, "because": "Wenig TDD-Unterstützung"}, {"text": "JavaScript", "correct": true, "because": "Jest und Mocha"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gut gewählte Programmiersprache in TDD?', 3, '[{"text": "Einfachere Testentwicklung", "correct": true, "because": "Tools verfügbar"}, {"text": "Schnellere Iterationen", "correct": true, "because": "Effiziente Tests"}, {"text": "Hohe Kosten", "correct": false, "because": "Nicht relevant"}, {"text": "Bessere Teamproduktivität", "correct": true, "because": "Kompetenz hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen kann die falsche Sprachauswahl in TDD mit sich bringen?', 4, '[{"text": "Fehlende Test-Frameworks", "correct": true, "because": "Erschwert TDD"}, {"text": "Lernaufwand für Team", "correct": true, "because": "Neue Sprache"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Eher Verzögerung"}, {"text": "Eingeschränkte Testbarkeit", "correct": true, "because": "Werkzeuge fehlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien sollten bei der Auswahl einer Sprache für TDD Priorität haben?', 3, '[{"text": "Unterstützung für Unit-Tests", "correct": true, "because": "TDD-Kern"}, {"text": "Team-Erfahrung", "correct": true, "because": "Effizienz steigt"}, {"text": "Code-Länge", "correct": false, "because": "Weniger relevant"}, {"text": "Verfügbarkeit von Tools", "correct": true, "because": "Fördert TDD"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Auswahl der Programmiersprache beeinflusst TDD-Erfolg. b) TDD ist nur mit Java effektiv.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sprache wichtig, nicht nur Java"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Test-Frameworks sind bei der Sprachauswahl für TDD entscheidend. b) Teamkompetenz ist irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Frameworks wichtig, Kompetenz zählt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Dynamische Sprachen wie Python erleichtern TDD. b) TDD ist sprachunabhängig.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Flexibilität hilft, Prinzip universell"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Sprachauswahl in TDD kann Testbarkeit beeinflussen. b) Statische Sprachen sind für TDD ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Testbarkeit abhängig, Statische geeignet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Community-Unterstützung ist bei der Sprachauswahl für TDD wichtig. b) Die Auswahl der Sprache hat keinen Einfluss auf TDD.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Community hilft, Einfluss real"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

